import { DASHBOARDS_FOLDER_UID } from './api/constants';
import type { DashboardMeta } from './api/dashboards';
import type { DataSourceSettings } from '@grafana/data';

export const CONFIGURATION_ROUTE = 'configuration'

export function dataSourceEditPage(dataSource: Pick<DataSourceSettings, 'uid'>) {
  return `/connections/datasources/edit/${dataSource.uid}`;
}

export function dashboardPage(dashboard: DashboardMeta) {
  return `/d/${dashboard.uid}`;
}

export function mainPage(pluginId: string) {
  return `/a/${pluginId}`;
}

export const DASHBOARDS_FOLDER_PAGE = `/dashboards/f/${DASHBOARDS_FOLDER_UID}`;
