import React from 'react';
import { Route, Routes } from 'react-router-dom';
import { AppRootProps } from '@grafana/data';
import { CONFIGURATION_ROUTE } from './routes';

const MainPage = React.lazy(() => import('./pages/MainPage'));
const ConfigurationPage = React.lazy(() => import('./pages/ConfigurationPage'));

function App(props: AppRootProps) {
  return (
    <Routes>
      <Route path={CONFIGURATION_ROUTE} element={<ConfigurationPage {...props.meta} />} />
      <Route path="*" element={<MainPage {...props.meta} />} />
    </Routes>
  );
}

export default App;
